var ctrl = GameObject.Find("Canvas_Lobby").GetComponent<Railbound.UI.LobbyUIController>();
var so = new UnityEditor.SerializedObject(ctrl);
var sb = new System.Text.StringBuilder();
var sp = so.GetIterator();
while (sp.NextVisible(true)) {
    if (sp.propertyType == UnityEditor.SerializedPropertyType.ObjectReference) {
        sb.AppendLine($"{sp.propertyPath}: {(sp.objectReferenceValue != null ? sp.objectReferenceValue.name : "null")}");
    } else if (sp.propertyType == UnityEditor.SerializedPropertyType.ArraySize) {
        sb.AppendLine($"{sp.propertyPath} (size: {sp.intValue})");
    }
}
return sb.ToString();
